// Include benchmark-specific definitions (N, TSTEPS for heat-3d)
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A and B as in the original C version:
 *
 *   A[i][j][k] = B[i][j][k] = (i + j + (n - k)) * 10 / n;
 *
 * Mapping from C arrays to Halide buffers:
 *   C: DATA_TYPE A[N][N][N] accessed as A[i][j][k]
 *   Halide: Buffer<num_t, 3> A(k, j, i)  // dim 0 = k, dim 1 = j, dim 2 = i
 *
 * So A[i][j][k] in C becomes A(k, j, i) in Halide.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 3> B) {
    Var k("k"), j("j"), i("i");

    Func init("init");
    // i, j, k here are the C-style indices; buffer indices are (k, j, i)
    Expr val = cast<num_t>(i + j + (n - k)) * cast<num_t>(10) / cast<num_t>(n);
    init(k, j, i) = val;

    // Realize into both A and B so that B initially equals A
    init.realize(A);
    init.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size and number of time steps.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 3D buffers.
    // Dimension order is (k, j, i) so that:
    //   A(i,j,k in C) <-> A(k, j, i) in Halide.
    Halide::Buffer<num_t, 3> A(n, n, n);
    Halide::Buffer<num_t, 3> B(n, n, n);

    // Initialize A and B.
    init_array(n, A, B);

    // Create ImageParams for A and B so that Halide pipelines can read them.
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam B_param(type_of<num_t>(), 3, "B_param");

    A_param.set(A);
    B_param.set(B);

    // Vars for 3D indexing (k, j, i) <-> (C's k, j, i).
    // Argument order in Funcs will be (k, j, i); by default, Halide will
    // generate loops in the order: i (outer), j, k (innermost), which gives
    // unit-stride traversal over k since dim 0 is contiguous in memory.
    Var k("k"), j("j"), i("i");

    // One time-step consists of:
    //   1) B = stencil(A)
    //   2) A = stencil(B)
    //
    // We'll express these as two separate Halide Funcs:
    //   B_from_A: reads A_param, writes into B
    //   A_from_B: reads B_param, writes into A
    //
    // We only update interior points (i,j,k in [1, n-2]), as in the
    // original C loops. The boundaries remain unchanged.
    Func B_from_A("B_from_A");
    Func A_from_B("A_from_B");

    Expr alpha = cast<num_t>(Expr(0.125));
    Expr two   = cast<num_t>(Expr(2.0));

    // --- Stage 1: B = stencil(A) ---
    {
        Expr centerA = A_param(k, j, i);

        // Keep the algebra exactly as in the original C/Halide code to
        // preserve floating-point behavior.
        Expr term_i = alpha *
                      (A_param(k, j, i + 1) - two * centerA + A_param(k, j, i - 1));
        Expr term_j = alpha *
                      (A_param(k, j + 1, i) - two * centerA + A_param(k, j - 1, i));
        Expr term_k = alpha *
                      (A_param(k + 1, j, i) - two * centerA + A_param(k - 1, j, i));

        B_from_A(k, j, i) = term_i + term_j + term_k + centerA;
    }

    // --- Stage 2: A = stencil(B) ---
    {
        Expr centerB = B_param(k, j, i);

        Expr term_i = alpha *
                      (B_param(k, j, i + 1) - two * centerB + B_param(k, j, i - 1));
        Expr term_j = alpha *
                      (B_param(k, j + 1, i) - two * centerB + B_param(k, j - 1, i));
        Expr term_k = alpha *
                      (B_param(k + 1, j, i) - two * centerB + B_param(k - 1, j, i));

        A_from_B(k, j, i) = term_i + term_j + term_k + centerB;
    }

    // -------------------------------------------------------------------
    // Scheduling for B_from_A and A_from_B
    //
    // Goals:
    //   * Keep k innermost (unit-stride accesses in memory).
    //   * Tile over (i, j) to improve cache locality of the 3D stencil.
    //   * Vectorize along k using the natural SIMD width for num_t.
    //   * Parallelize over spatial tiles to exploit the many-core CPU.
    //
    // We do not change the time-stepping structure (outer C++ loop over t),
    // nor do we fuse the two stencils; B_from_A still computes a full B
    // field before A_from_B consumes it, preserving Jacobi semantics.
    // -------------------------------------------------------------------

    // Discover a good vector width for the current host and element type.
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;
    }

    // Tile sizes for i and j (C's slow dimensions).
    // These are deliberately modest so they work well across a range of N.
    const int tile_i = 8;
    const int tile_j = 8;

    // New Vars for tiling and fused-tile parallelization.
    Var io("io"), jo("jo"), ii("ii"), ji("ji"), tile_index("tile_index");

    // Helper lambda to apply the same schedule to both stencils.
    auto schedule_stencil = [&](Func &f) {
        // Tile the (i, j) space; keep k as a separate (innermost) dimension.
        // TailStrategy::GuardWithIf ensures correct behavior when (n-2) is
        // not a multiple of the tile size by guarding out-of-range iterations.
        f.tile(i, j, io, jo, ii, ji, tile_i, tile_j, TailStrategy::GuardWithIf)
         // Fuse the outer tile indices so we can parallelize over a single
         // 1D index and avoid nested parallelism.
         .fuse(jo, io, tile_index)
         // Reorder loops so that:
         //   outermost : tile_index (parallel tiles in i,j)
         //   then      : ji, ii    (within-tile j and i)
         //   innermost : k         (contiguous in memory, good for SIMD)
         .reorder(k, ii, ji, tile_index)
         // Vectorize along contiguous k-dimension.
         .vectorize(k, vec_width)
         // Parallelize across spatial tiles; each tile is independent.
         .parallel(tile_index);
    };

    schedule_stencil(B_from_A);
    schedule_stencil(A_from_B);

    // We want to update only the interior region:
    //   i, j, k in [1, n-2]
    // The boundary values remain unchanged (exactly as in the C code).
    //
    // We'll realize into cropped "interior" views that alias the
    // underlying A and B storage, so that:
    //   - interior points are overwritten by the stencil
    //   - boundary points (index 0 and n-1) are untouched
    Halide::Buffer<num_t, 3> B_interior =
        B.cropped(0, 1, n - 2)
         .cropped(1, 1, n - 2)
         .cropped(2, 1, n - 2);

    Halide::Buffer<num_t, 3> A_interior =
        A.cropped(0, 1, n - 2)
         .cropped(1, 1, n - 2)
         .cropped(2, 1, n - 2);

    // Compile the kernels ahead of time to avoid measuring JIT cost.
    B_from_A.compile_jit(target);
    A_from_B.compile_jit(target);

    // Time the tsteps iterations.
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // First half-step: B = stencil(A) on the interior.
        B_from_A.realize(B_interior);

        // Second half-step: A = stencil(B) on the interior.
        A_from_B.realize(A_interior);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print out the final A array (similar to print_array in C).
    using namespace std::string_literals;
